entry.summary:
Promises are central to modern JavaScript, but most developers use only the basics. Firefox fully implements the Promise specification and the full Promise static API. This guide covers practical patterns: error handling, concurrency control, cancellation, and the less-used Promise methods.
// Creating a Promise
const p = new Promise((resolve, reject) => {
  // Async operation
  setTimeout(() => {
    if (success) resolve(value);
    else reject(new Error('failed'));
  }, 1000);
});

// Consuming
p.then(value => console.log(value))
 .catch(err => console.error(err))
 .finally(() => cleanup());

// Async/await style (same thing, nicer syntax)
try {
  const value = await p;
} catch (err) {
  console.error(err);
} finally {
  cleanup();
}

